import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {createRequire} from 'node:module';
const require=createRequire(new URL('../runtime/package.json',import.meta.url)),{JSDOM}=require('jsdom'),code=name=>fs.readFileSync(new URL('../public/document-study/'+name+'.js',import.meta.url),'utf8'),tick=()=>new Promise(resolve=>setTimeout(resolve,20));
function fixture(){const dom=new JSDOM('<header id="c3-tabstrip"><details class="ht-switch"><summary>Project</summary></details></header><div id="app"><main id="workspace"><header id="c3-surface-bar"><div class="sb-right"><details class="sb-morew"><summary class="sb-btn">More</summary><div class="sb-menu"></div></details></div></header><div class="workbar"><div class="draft-surface-actions"></div></div><div class="desk"><article class="document"><h1>Exact title</h1><div id="manuscript" contenteditable="true"><p>Exact kept human words.</p></div></article><aside id="margin">Existing margin</aside></div><div class="draft-bar"><details class="draft-inspect"><summary>History</summary><p>Actual prior saved history</p></details></div></main></div>',{runScripts:'outside-only',url:'http://localhost/document-study/'}),w=dom.window,p={id:'parent',name:'Invented piece',title:'Exact title',view:'article',viewedStage:5},binding={id:'part-one',parentStudyId:'parent',title:'Original part'},proof={bindingId:'part-one',parentStudyId:'parent',sequence:1,dirty:false,expected:{hash:'saved'}},requests=[],posts=[];w.structuredClone=structuredClone;w.current=()=>p;w.state={projects:[p]};w.matchMedia=()=>({matches:false});w.viewPhase=async n=>{p.view='record';p.viewedStage=n;};w.render=()=>{};w.studyDraft={currentBinding:()=>binding,currentProof:()=>proof,showHistory:async()=>{}};w.c3Shell={register(_name,fn){fn();}};const proposed={id:'proposal-one',status:'pending',stale:false,expected:proof.expected,replacements:[{before:'Exact kept human words.',words:'Invented proposed wording.'}]};w.fetch=async(url,options)=>{const q=new URL(url,w.location.href),action=q.pathname.split('/').at(-1);requests.push({action,bindingId:q.searchParams.get('bindingId')});if(options?.method==='POST')posts.push({action,body:JSON.parse(options.body)});return {ok:true,json:async()=>action==='requests'?{items:[{id:'proposal-one',status:'pending'}]}:action==='read'?{binding:{id:binding.id,parentStudyId:binding.parentStudyId},context:{records:[{id:'source-one',title:'Retained source',role:'source',copiedHash:'a'.repeat(64)}]}}:{...proposed}};};w.eval(code('study-ai-proposals'));w.eval(code('workbench-frame'));return{w,d:w.document,p,binding,proof,posts,requests,proposed,close:()=>w.close()};}
async function open(f){f.d.querySelector('[data-ai-entry]').click();await tick();assert.ok(f.d.querySelector('[data-ai-action="review:proposal-one"]'));f.d.querySelector('[data-ai-action="review:proposal-one"]').click();await tick();}
test('existing proposal entrance opens its original reviewer beside the unchanged editor',async()=>{const f=fixture();try{const editor=f.d.querySelector('#manuscript'),before=editor.parentElement;await open(f);assert.ok(f.d.querySelector('#wbf-drawer #study-ai-proposals'));assert.equal(editor.parentElement,before);assert.equal(editor.textContent,'Exact kept human words.');assert.match(f.d.querySelector('#wbf-drawer').textContent,/Before|Proposed|Invented proposed wording/);assert.equal(f.d.querySelector('[data-ai-entry]').getAttribute('aria-expanded'),'true');assert.equal(f.posts.length,0);}finally{f.close();}});
test('drawer close and reopen retain selected proposal and exact rejection input without deciding',async()=>{const f=fixture();try{await open(f);const reason=f.d.querySelector('[data-ai-reason]');reason.value='Keep my exact uncertainty 瓷.';reason.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.d.querySelector('[data-wbf-close]').click();await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.d.querySelector('#study-ai-proposals'),null);assert.equal(f.d.querySelector('[data-ai-entry]').getAttribute('aria-expanded'),'false');f.d.querySelector('[data-ai-entry]').click();await tick();assert.equal(f.d.querySelector('#wbf-drawer [data-ai-reason]').value,reason.value);assert.equal(f.posts.length,0);}finally{f.close();}});
test('another drawer and scope changes never leak proposal controls, while retained reason stays scoped',async()=>{const f=fixture();try{await open(f);let reason=f.d.querySelector('[data-ai-reason]');reason.value='Only this first part.';reason.dispatchEvent(new f.w.Event('input',{bubbles:true}));await f.w.c3WorkbenchFrame.openTool('history');assert.equal(f.d.querySelector('#wbf-drawer #study-ai-proposals'),null);assert.match(f.d.querySelector('#wbf-drawer').textContent,/Actual prior saved history/);f.d.querySelector('[data-ai-entry]').click();await tick();f.binding.id='part-two';f.proof.bindingId='part-two';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.d.querySelector('#study-ai-proposals'),null);f.d.querySelector('[data-ai-entry]').click();await tick();assert.doesNotMatch(f.d.querySelector('#wbf-drawer').textContent,/Only this first part/);f.binding.id='part-one';f.proof.bindingId='part-one';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();await tick();f.d.querySelector('[data-ai-entry]').click();await tick();assert.equal(f.d.querySelector('#wbf-drawer [data-ai-reason]').value,'Only this first part.');assert.equal(f.posts.length,0);}finally{f.close();}});
test('dirty or stale proposal stays human reviewed with Apply refused and typed reason retained',async()=>{const f=fixture();try{await open(f);const input=f.d.querySelector('[data-ai-reason]');input.value='Retained review reason';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.proof.dirty=true;f.w.dispatchEvent(new f.w.Event('study-draft-change'));await tick();assert.equal(f.d.querySelector('#wbf-drawer [data-ai-action="apply"]').disabled,true);assert.equal(f.d.querySelector('[data-ai-reason]').value,input.value);assert.match(f.d.querySelector('#wbf-drawer').textContent,/Browser edits are unsaved/);assert.equal(f.posts.length,0);}finally{f.close();}});
test('closing and immediately reopening during a delayed list read finishes with a current list',async()=>{const f=fixture();let release;const gate=new Promise(resolve=>release=resolve),request=f.w.fetch;let reads=0;f.w.fetch=async(...args)=>{if(++reads===1)await gate;return request(...args);};try{f.d.querySelector('[data-ai-entry]').click();await tick();f.d.querySelector('[data-wbf-close]').click();f.d.querySelector('[data-ai-entry]').click();await tick();release();await tick();await tick();assert.ok(f.d.querySelector('#wbf-drawer [data-ai-action="review:proposal-one"]'));assert.equal(f.requests.filter(r=>r.action==='requests').length,2);assert.equal(f.posts.length,0);}finally{f.close();}});
test('Escape retains unfinished rejection reason and a stale review cannot enable Apply',async()=>{const f=fixture();try{f.proposed.stale=true;f.proposed.reason='Source changed';await open(f);const input=f.d.querySelector('[data-ai-reason]');input.value='Exact unfinished reason';input.dispatchEvent(new f.w.Event('input',{bubbles:true}));assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);f.d.dispatchEvent(new f.w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);f.d.querySelector('[data-ai-entry]').click();await tick();assert.equal(f.d.querySelector('#wbf-drawer [data-ai-reason]').value,input.value);assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);assert.equal(f.posts.length,0);}finally{f.close();}});
test('late proposal response cannot enter another project drawer',async()=>{const f=fixture();let release;const gate=new Promise(resolve=>release=resolve),request=f.w.fetch;f.w.fetch=async(...args)=>{await gate;return request(...args);};try{f.d.querySelector('[data-ai-entry]').click();await tick();f.p.id='other-project';f.binding.id='other-part';f.binding.parentStudyId=f.p.id;f.proof.bindingId=f.binding.id;f.proof.parentStudyId=f.p.id;f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();release();await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.d.querySelector('#study-ai-proposals'),null);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');assert.equal(f.posts.length,0);}finally{f.close();}});
test('opening proposals leaves Focus through its maintained margin control without replacing words',async()=>{const f=fixture();try{f.d.querySelector('#workspace').classList.add('workspace');const top=f.d.createElement('div');top.className='topbar';top.innerHTML='<button data-surface-mode="margin">Margin</button>';f.d.querySelector('#workspace').prepend(top);let exits=0;top.querySelector('button').onclick=()=>{exits++;f.d.body.dataset.draftFocus='false';};f.d.body.dataset.draftFocus='true';const editor=f.d.querySelector('#manuscript');await open(f);assert.equal(exits,1);assert.equal(f.d.body.dataset.draftFocus,'false');assert.equal(f.d.querySelector('#manuscript'),editor);assert.ok(f.d.querySelector('#wbf-drawer #study-ai-proposals'));assert.equal(f.posts.length,0);}finally{f.close();}});
