function openings(f){Object.assign(f.proposed,{purpose:'opening-options',replacements:[],openingOptions:[{id:'option-one',words:'I keep the uncertainty.'},{id:'option-two',words:'I begin with the observed cup.'}]});}
test('opening drawer requires a deliberate choice and retains it across close without writing',async()=>{const f=fixture();try{openings(f);await open(f);assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);assert.equal(f.d.querySelector('input[type=radio]:checked'),null);const option=f.d.querySelector('[data-ai-opening-option="option-two"]');option.checked=true;option.dispatchEvent(new f.w.Event('change',{bubbles:true}));assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,false);assert.equal(f.d.querySelector('[data-ai-action="apply"]').textContent,'Use selected opening');f.d.querySelector('[data-wbf-close]').click();await tick();f.d.querySelector('[data-ai-entry]').click();await tick();assert.equal(f.d.querySelector('[data-ai-opening-option="option-two"]').checked,true);assert.equal(f.posts.length,0);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
test('opening review cannot bypass the existing host human-approval flag',async()=>{const f=fixture();try{openings(f);f.w.AR_CREATE_REVIEW_MODE={actualWork:true,studyDraftCorrections:true,studyDraftApprovals:false};await open(f);const option=f.d.querySelector('[data-ai-opening-option]');option.checked=true;option.dispatchEvent(new f.w.Event('change',{bubbles:true}));assert.match(f.d.querySelector('#wbf-drawer').textContent,/Human approval is unavailable in this review/);assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);assert.equal(f.d.querySelector('[data-ai-action="reject"]').disabled,true);f.d.querySelector('[data-ai-action="apply"]').disabled=false;f.d.querySelector('[data-ai-action="apply"]').click();await tick();assert.equal(f.posts.length,0);}finally{f.close();}});
test('prepared opening handoff opens the exact request in the existing drawer and refuses another scope',async()=>{const f=fixture();try{openings(f);f.proposed.status='prepared';f.proposed.openingOptions=[];await f.w.studyAIProposals.openPrepared({bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId,requestId:f.proposed.id});assert.ok(f.d.querySelector('#wbf-drawer #study-ai-proposals'));assert.match(f.d.querySelector('#wbf-drawer').textContent,/Exact context prepared/);assert.equal(f.posts.length,0);await assert.rejects(f.w.studyAIProposals.openPrepared({bindingId:'foreign',parentStudyId:f.binding.parentStudyId,requestId:f.proposed.id}),/another working part/);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
test('invented opening choice sends only its stored option identity to the existing human decision',async()=>{const f=fixture();try{openings(f);f.w.AR_CREATE_REVIEW_MODE={actualWork:true,studyDraftCorrections:true,studyDraftApprovals:true};const request=f.w.fetch;f.w.fetch=async(url,options)=>{const result=await request(url,options);if(new URL(url,f.w.location.href).pathname.endsWith('/accept')){Object.assign(f.proposed,{status:'accepted',selectedOptionId:JSON.parse(options.body).optionId,continuationReadiness:{eligible:true,sourceIds:['retained-source'],answerIds:[]}});return{ok:true,json:async()=>({binding:f.binding})};}return result;};f.w.studyDraft.refreshSaved=async()=>{f.proof.sequence++;};await open(f);const option=f.d.querySelector('[data-ai-opening-option="option-two"]');option.checked=true;option.dispatchEvent(new f.w.Event('change',{bubbles:true}));f.d.querySelector('[data-ai-action="apply"]').click();await tick();assert.equal(f.posts.length,1);assert.equal(f.posts[0].action,'accept');assert.equal(f.posts[0].body.requestId,'proposal-one');assert.equal(f.posts[0].body.optionId,'option-two');assert.match(f.posts[0].body.operationId,/^[a-f0-9-]{36}$/);assert.deepEqual(Object.keys(f.posts[0].body).sort(),['operationId','optionId','requestId']);assert.match(f.d.querySelector('#wbf-drawer').textContent,/Acceptance is recorded/);assert.ok(f.d.querySelector('[data-ai-action="continue-article"]'));}finally{f.close();}});
test('malformed pending opening without available options stays read only',async()=>{const f=fixture();try{openings(f);f.proposed.openingOptions=[];await open(f);assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);assert.equal(f.posts.length,0);}finally{f.close();}});
for(const delayed of ['requests','review'])test('prepared opening respects explicit close during deferred '+delayed,async()=>{const f=fixture();let release;const gate=new Promise(r=>release=r);try{openings(f);await open(f);const request=f.w.fetch;let deferred=false;f.w.fetch=async(url,...args)=>{if(!deferred&&new URL(url,f.w.location.href).pathname.endsWith('/'+delayed)){deferred=true;await gate;}return request(url,...args);};const pending=f.w.studyAIProposals.openPrepared({bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId,requestId:f.proposed.id});const refused=assert.rejects(pending,/cancelled|changed/);await tick();assert.equal(deferred,true);f.d.querySelector('[data-wbf-close]').click();assert.equal(f.d.querySelector('#wbf-drawer'),null);release();await refused;await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.w.studyAIProposals.isOpen(),false);assert.equal(f.posts.length,0);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{release?.();f.close();}});
for(const delayed of ['requests','review'])test('prepared opening cannot survive scope away and back during deferred '+delayed,async()=>{const f=fixture();let release;const gate=new Promise(r=>release=r);try{openings(f);const request=f.w.fetch;let deferred=false;f.w.fetch=async(url,...args)=>{if(!deferred&&new URL(url,f.w.location.href).pathname.endsWith('/'+delayed)){deferred=true;await gate;}return request(url,...args);};const pending=f.w.studyAIProposals.openPrepared({bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId,requestId:f.proposed.id});const refused=assert.rejects(pending,/cancelled|changed/);await tick();assert.equal(deferred,true);f.binding.id='other-part';f.proof.bindingId='other-part';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();f.binding.id='part-one';f.proof.bindingId='part-one';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();release();await refused;await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.w.studyAIProposals.isOpen(),false);assert.equal(f.posts.length,0);}finally{release?.();f.close();}});
test('prepared exact request refreshes an already open proposal drawer without toggling it closed',async()=>{const f=fixture();try{openings(f);await open(f);const drawer=f.d.querySelector('#wbf-drawer');await f.w.studyAIProposals.openPrepared({bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId,requestId:f.proposed.id});assert.equal(f.d.querySelector('#wbf-drawer'),drawer);assert.equal(f.w.studyAIProposals.isOpen(),true);assert.equal(f.d.querySelectorAll('#study-ai-proposals').length,1);assert.equal(f.posts.length,0);}finally{f.close();}});

test('accepted eligible opening explicitly prepares continuation in the same reviewer without generating or applying',async()=>{const f=fixture();try{openings(f);Object.assign(f.proposed,{status:'accepted',selectedOptionId:'option-two',continuationReadiness:{eligible:true,sourceIds:['retained-source'],answerIds:[]}});const request=f.w.fetch,continuationId='33333333-3333-4333-8333-333333333333';f.w.fetch=async(url,options)=>{const result=await request(url,options),u=new URL(url,f.w.location.href);if(u.pathname.endsWith('/prepare'))return{ok:true,json:async()=>({id:continuationId,purpose:'article-continuation',binding:{bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId},expected:f.proof.expected,modelExecuted:false})};if(u.pathname.endsWith('/review')&&u.searchParams.get('requestId')===continuationId)return{ok:true,json:async()=>({id:continuationId,purpose:'article-continuation',status:'prepared',stale:false,expected:f.proof.expected,replacements:[],continuation:{opening:{words:'I begin with the observed cup.'}}})};return result;};await open(f);const action=f.d.querySelector('[data-ai-action="continue-article"]');assert.ok(action);assert.equal(action.disabled,false);assert.equal(f.posts.length,0);action.click();await tick();assert.equal(f.posts.length,1);assert.equal(f.posts[0].action,'prepare');assert.deepEqual(JSON.parse(JSON.stringify(f.posts[0].body)),{purpose:'article-continuation',openingRequestId:'proposal-one',selectedOptionId:'option-two',sourceIds:['retained-source'],answerIds:[]});assert.match(f.d.querySelector('#wbf-drawer').textContent,/continuation.*prepared/i);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
function continuationReady(f){openings(f);Object.assign(f.proposed,{status:'accepted',selectedOptionId:'option-two',continuationReadiness:{eligible:true,sourceIds:['retained-source'],answerIds:[]}});const request=f.w.fetch,id='44444444-4444-4444-8444-444444444444';f.w.fetch=async(url,options)=>{const result=await request(url,options),u=new URL(url,f.w.location.href);if(u.pathname.endsWith('/prepare'))return{ok:true,json:async()=>({id,purpose:'article-continuation',binding:{bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId},expected:f.proof.expected,modelExecuted:false})};if(u.pathname.endsWith('/review')&&u.searchParams.get('requestId')===id)return{ok:true,json:async()=>({id,purpose:'article-continuation',status:'prepared',stale:false,expected:f.proof.expected,replacements:[],continuation:{opening:{words:'I begin with the observed cup.'}}})};return result;};return id;}
for(const delayed of ['prepare','review'])test('closing a deferred article continuation '+delayed+' retains the closed review intent',async()=>{const f=fixture();let release;try{const continuationId=continuationReady(f);await open(f);const request=f.w.fetch,gate=new Promise(r=>release=r);let held=false;f.w.fetch=async(url,...args)=>{const u=new URL(url,f.w.location.href);if(!held&&u.pathname.endsWith('/'+delayed)&&(delayed==='prepare'||u.searchParams.get('requestId')===continuationId)){held=true;await gate;}return request(url,...args);};f.d.querySelector('[data-ai-action="continue-article"]').click();await tick();assert.equal(held,true);f.d.querySelector('[data-wbf-close]').click();release();await tick();await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.w.studyAIProposals.isOpen(),false);assert.equal(f.posts.some(p=>p.action==='accept'||p.action==='propose'),false);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{release?.();f.close();}});
test('continuation cannot resume after scope away and back while preparation is pending',async()=>{const f=fixture();let release;try{continuationReady(f);await open(f);const request=f.w.fetch,gate=new Promise(r=>release=r);f.w.fetch=async(url,...args)=>{if(new URL(url,f.w.location.href).pathname.endsWith('/prepare'))await gate;return request(url,...args);};f.d.querySelector('[data-ai-action="continue-article"]').click();await tick();f.binding.id='other-part';f.proof.bindingId='other-part';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();f.binding.id='part-one';f.proof.bindingId='part-one';f.w.studyAIProposals.mount();f.w.c3WorkbenchFrame.decorate();release();await tick();await tick();assert.equal(f.d.querySelector('#wbf-drawer'),null);assert.equal(f.w.studyAIProposals.isOpen(),false);assert.equal(f.posts.some(p=>p.action==='accept'||p.action==='propose'),false);}finally{release?.();f.close();}});
test('pending continuation reads as continuous paragraphs and respects disabled human approval',async()=>{const f=fixture();try{Object.assign(f.proposed,{purpose:'article-continuation',continuation:{opening:{words:'Exact chosen opening.'}},replacements:[{id:'derived-one',before:'',words:'First proposed ordinary paragraph.',continuationInsertion:true},{id:'derived-two',before:'',words:'Second proposed ordinary paragraph.',continuationInsertion:true}]});f.w.AR_CREATE_REVIEW_MODE={actualWork:true,studyDraftCorrections:true,studyDraftApprovals:false};await open(f);const reading=f.d.querySelector('.study-ai-continuation');assert.deepEqual([...reading.querySelectorAll('p')].map(p=>p.textContent),['Exact chosen opening.','First proposed ordinary paragraph.','Second proposed ordinary paragraph.']);assert.doesNotMatch(reading.textContent,/Before/);assert.equal(f.d.querySelector('[data-ai-action="apply"]').disabled,true);f.d.querySelector('[data-ai-action="apply"]').disabled=false;f.d.querySelector('[data-ai-action="apply"]').click();await tick();assert.equal(f.posts.length,0);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
