function sourced(f,{gapsOnly=false}={}){Object.assign(f.proposed,{purpose:'sourced-paragraph',replacements:gapsOnly?[]:[{id:'inserted',before:'',words:'A quiet garden was observed.'}],sourcedEvidence:{schema:'ar-create.native-sourced-proposal.v1',contextHash:'c'.repeat(64),traceabilityOnly:true,claims:gapsOnly?[]:[{text:'A quiet garden was observed.',citations:[{sourceId:'source-one',sourceHash:'a'.repeat(64),start:0,end:30,quote:'The invented garden was quiet.',sourceRole:'source'}]}],gaps:[{question:'When did the gardener arrive?',answerableBy:null}]}});}
