test('prepare and explicit bounded run stage proposal without auto acceptance, polling or writer save',async()=>{const f=fixture(),operation='12345678-1234-4234-8234-123456789abc';try{sourced(f);f.w.crypto.randomUUID=()=>operation;let checks=0;const request=f.w.fetch;f.w.fetch=async(url,options)=>{const path=new URL(url,f.w.location.href).pathname;if(path.endsWith('/prepare')){const body=JSON.parse(options.body);f.posts.push({action:'prepare',body});return {ok:true,json:async()=>({id:f.proposed.id,purpose:'sourced-paragraph',binding:{bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId}})};}if(path.endsWith('/run')){const body=options?.method==='POST'?JSON.parse(options.body):null;if(body)f.posts.push({action:'run',body});else checks++;return {ok:true,json:async()=>({state:body?'running':'complete',requestId:f.proposed.id,operationId:operation})};}return request(url,options);};f.proposed.status='prepared';await open(f);const instruction=f.d.querySelector('[data-ai-instruction]');instruction.value='Keep the uncertainty.';instruction.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.d.querySelector('[data-ai-action="prepare-sourced"]').click();await tick();assert.equal(f.posts.find(p=>p.action==='prepare').body.instruction,'Keep the uncertainty.');assert.deepEqual(f.posts.find(p=>p.action==='prepare').body.sourceIds,['source-one']);f.d.querySelector('[data-ai-action="run-ai"]').click();await tick();assert.equal(f.posts.filter(p=>p.action==='run').length,1);assert.equal(checks,0);assert.deepEqual(f.posts.find(p=>p.action==='run').body,{bindingId:'part-one',parentStudyId:'parent',requestId:'proposal-one',operationId:operation});f.proposed.status='pending';f.d.querySelector('[data-ai-action="check-run"]').click();await tick();assert.equal(checks,1);assert.match(f.d.querySelector('.study-ai-status').textContent,/Paragraph proposed/);await tick();assert.equal(checks,1);assert.equal(f.posts.some(p=>p.action==='accept'),false);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
