test('stand-in decisions use copy-scoped endpoint with actual agent and no human contract fields',async()=>{for(const action of ['apply','reject']){const f=fixture();try{sourced(f);f.proposed.canStandInReview=true;f.w.arCreateUiActor={actor:'agent:codex'};f.w.AR_CREATE_REVIEW_MODE={actualWork:true,studyDraftApprovals:false};f.w.studyDraft.refreshSaved=async()=>{};const request=f.w.fetch;let savedActor;f.w.fetch=async(url,options)=>{if(url==='/api/study/structure-tests/proposal-review'){savedActor=f.w.arCreateUiActor.actor;const body=JSON.parse(options.body);f.posts.push({action:'stand-in',body});return {ok:true,json:async()=>({id:f.proposed.id,status:body.action==='accept'?'accepted':'rejected',binding:{id:f.binding.id,parentStudyId:f.binding.parentStudyId}})};}return request(url,options);};await open(f);const reason=f.d.querySelector('[data-ai-reason]');reason.value='Agent stand-in reason';reason.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.d.querySelector('[data-ai-action="'+action+'"]').click();await tick();const post=f.posts.find(p=>p.action==='stand-in');assert.ok(post);assert.equal(post.body.action,action==='apply'?'accept':'reject');assert.equal(post.body.bindingId,f.binding.id);assert.equal(post.body.parentStudyId,f.binding.parentStudyId);assert.equal(post.body.requestId,f.proposed.id);assert.ok(post.body.operationId);if(action==='reject')assert.equal(post.body.reason,'Agent stand-in reason');assert.equal(post.body.humanDecision,undefined);assert.equal(post.body.expectedContractHash,undefined);assert.equal(post.body.actor,undefined);assert.equal(savedActor,'agent:codex');assert.equal(f.w.arCreateUiActor.actor,'agent:codex');assert.equal(f.posts.some(p=>['accept','reject','human-contract'].includes(p.action)),false);}finally{f.close();}}});
