test('native source selection defaults only evidence records and sends exact chosen IDs',async()=>{const f=fixture();try{sourced(f);let captured;const request=f.w.fetch;f.w.fetch=async(url,options)=>{const action=new URL(url,f.w.location.href).pathname.split('/').at(-1);if(action==='read')return {ok:true,json:async()=>({binding:{id:f.binding.id,parentStudyId:f.binding.parentStudyId},sourceCatalog:[{id:'source-one',title:'Retained source',role:'source',hash:'a'.repeat(64),canPrepare:true},{id:'map-one',title:'Saved map',role:'map',hash:'b'.repeat(64),canPrepare:true},{id:'missing',title:'Unavailable',role:'source',hash:'c'.repeat(64),missing:true,canPrepare:false}]})};if(action==='prepare'){captured=JSON.parse(options.body);return {ok:true,json:async()=>({id:f.proposed.id,purpose:'sourced-paragraph',binding:{bindingId:f.binding.id,parentStudyId:f.binding.parentStudyId}})};}return request(url,options);};f.proposed.status='prepared';await open(f);assert.deepEqual([...f.d.querySelectorAll('[data-ai-source-id]:checked')].map(n=>n.dataset.aiSourceId),['source-one']);assert.match(f.d.querySelector('.study-ai-source-choices').textContent,/Saved map.*provisional context/);assert.equal(f.d.querySelector('[data-ai-source-id="missing"]'),null);const source=f.d.querySelector('[data-ai-source-id="source-one"]');source.checked=false;source.dispatchEvent(new f.w.Event('change',{bubbles:true}));assert.equal(f.d.querySelector('[data-ai-action="prepare-sourced"]').disabled,true);const currentSource=f.d.querySelector('[data-ai-source-id="source-one"]');currentSource.checked=true;currentSource.dispatchEvent(new f.w.Event('change',{bubbles:true}));const map=f.d.querySelector('[data-ai-source-id="map-one"]');map.checked=true;map.dispatchEvent(new f.w.Event('change',{bubbles:true}));f.d.querySelector('[data-ai-action="prepare-sourced"]').click();await tick();assert.deepEqual(captured.sourceIds,['source-one','map-one']);assert.equal(f.posts.some(p=>p.action==='run'),false);}finally{f.close();}});
