function nativeMargin(f,{actor='agent:codex',standIn=true}={}){const margin=f.d.getElementById('margin');margin.className='margin mobileVisible wbf-margin';margin.innerHTML='<div class="draft-surface-margin-body"><p class="retained-note">Retained passage note.</p></div>';const editor=f.d.getElementById('manuscript');editor.firstElementChild.dataset.block='ending';f.w.arCreateUiActor={actor};f.w.AR_CREATE_REVIEW_MODE={actualWork:true,studyDraftApprovals:!standIn};let contracts={hash:'c'.repeat(64),protections:[],pieceGuidance:[],canStandInContracts:standIn},native={binding:{id:f.binding.id,parentStudyId:f.binding.parentStudyId},expected:f.proof.expected,projection:[{id:'ending',words:editor.textContent,blockHash:'b'.repeat(64),proposalEditable:true}],context:{records:[{id:'source-one',title:'Retained source title',role:'source',copiedHash:'a'.repeat(64)}]},aiExecution:{available:true}};const request=f.w.fetch;f.w.fetch=async(url,options)=>{const action=new URL(url,f.w.location.href).pathname.split('/').at(-1);if(action==='read')return {ok:true,json:async()=>native};if(action==='contracts')return {ok:true,json:async()=>contracts};if(['proposal-contract','human-contract'].includes(action)){const body=JSON.parse(options.body);f.posts.push({action,body});if(body.kind==='protect')contracts={...contracts,protections:[{id:'protection-one',text:body.text,active:true}]};if(body.kind==='release-protection')contracts={...contracts,protections:[]};if(body.kind==='set-piece-guidance')contracts={...contracts,pieceGuidance:[{key:body.key,body:body.body,role:'instruction-not-facts',decisionRole:standIn?'stand-in':'human',actor}]};if(body.kind==='clear-piece-guidance')contracts={...contracts,pieceGuidance:[]};return {ok:true,json:async()=>contracts};}return request(url,options);};f.w.studyAIProposals.mount();return {margin,editor,get contracts(){return contracts},native};}
test('native proposals remain the same visible ending card before and after optional drawer',async()=>{const f=fixture();try{const n=nativeMargin(f);await tick();const host=f.d.getElementById('study-ai-proposals'),note=f.d.querySelector('.retained-note'),body=note.parentElement;assert.equal(host.parentElement,body);assert.equal(body.lastElementChild,host);assert.equal(body.firstElementChild,note);assert.equal(host.hidden,false);assert.equal(f.w.studyAIProposals.hasExecution(),true);const text=n.editor.firstElementChild.firstChild,range=f.d.createRange();range.setStart(text,2);range.setEnd(text,7);f.w.getSelection().addRange(range);n.editor.scrollTop=31;const prior=f.w.getSelection().anchorNode;n.editor.getBoundingClientRect=()=>({width:600,left:20,right:620});n.margin.getBoundingClientRect=()=>({left:650,right:850});n.editor.firstElementChild.getBoundingClientRect=()=>({top:700});host.getBoundingClientRect=()=>({top:100+(parseFloat(host.style.marginTop)||20)});f.w.dispatchEvent(new f.w.Event('resize'));assert.equal(host.style.marginTop,'600px');assert.equal(host.dataset.endingBlock,'ending');f.d.querySelector('[data-ai-entry]').click();await tick();assert.equal(f.d.querySelector('#wbf-drawer #study-ai-proposals'),host);f.d.querySelector('[data-wbf-close]').click();await tick();assert.equal(f.d.getElementById('study-ai-proposals'),host);assert.equal(host.parentElement,body);assert.equal(note.parentElement,body);assert.equal(n.editor.scrollTop,31);assert.equal(f.w.getSelection().anchorNode,prior);assert.equal(f.posts.length,0);}finally{f.close();}});
test('exact saved native selection protects and releases through copy contract without human impersonation',async()=>{const f=fixture();try{const n=nativeMargin(f);await tick();const text=n.editor.firstElementChild.firstChild,range=f.d.createRange();range.setStart(text,6);range.setEnd(text,10);f.w.getSelection().removeAllRanges();f.w.getSelection().addRange(range);f.d.dispatchEvent(new f.w.Event('selectionchange'));const protect=f.d.querySelector('[data-ai-action="protect-selection"]');assert.equal(protect.disabled,false);protect.click();await tick();const saved=f.posts.find(p=>p.action==='proposal-contract');assert.equal(saved.body.kind,'protect');assert.deepEqual({text:saved.body.text,from:saved.body.from,to:saved.body.to,paragraphId:saved.body.paragraphId},{text:'kept',from:6,to:10,paragraphId:'ending'});assert.equal(saved.body.seenBlockHash,'b'.repeat(64));assert.deepEqual(saved.body.expected,f.proof.expected);assert.equal(saved.body.humanDecision,undefined);assert.equal(f.w.arCreateUiActor.actor,'agent:codex');assert.equal(f.d.querySelector('[data-ai-action^="release:"]').disabled,true);const reason=f.d.querySelector('[data-ai-contract-reason]');reason.value='Release this test-only selection';reason.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.d.querySelector('[data-ai-action^="release:"]').click();await tick();assert.equal(f.posts.at(-1).body.kind,'release-protection');assert.equal(f.posts.at(-1).body.reason,reason.value);assert.equal(n.editor.textContent,'Exact kept human words.');assert.equal(f.posts.some(p=>p.action==='human-contract'),false);}finally{f.close();}});
test('piece guidance uses exact copy route and original human route with editable scoped instructions',async()=>{for(const standIn of [true,false]){const f=fixture();try{nativeMargin(f,{standIn,actor:standIn?'agent:codex':'human:adrian'});await tick();f.d.querySelector('[data-ai-action="guidance-open"]').click();const body=f.d.querySelector('[data-ai-guidance-body]');body.value='Keep this piece uncertain and concrete.';body.dispatchEvent(new f.w.Event('input',{bubbles:true}));assert.equal(f.d.querySelector('[data-ai-action="guidance-save"]').disabled,false);f.d.querySelector('[data-ai-action="guidance-save"]').click();await tick();const post=f.posts.find(p=>p.action===(standIn?'proposal-contract':'human-contract'));assert.equal(post.body.kind,'set-piece-guidance');assert.equal(post.body.key,'voice');assert.equal(post.body.body,body.value);assert.equal(post.body.humanDecision,standIn?undefined:true);assert.match(f.d.querySelector('.study-ai-guidance').textContent,/instruction, not evidence/);const reason=f.d.querySelector('[data-ai-contract-reason]');reason.value='Return to the shared sheet';reason.dispatchEvent(new f.w.Event('input',{bubbles:true}));f.d.querySelector('[data-ai-action="guidance-clear"]').click();await tick();assert.equal(f.posts.at(-1).body.kind,'clear-piece-guidance');assert.equal(f.posts.at(-1).body.reason,'Return to the shared sheet');assert.equal(f.d.getElementById('manuscript').textContent,'Exact kept human words.');}finally{f.close();}}});
