test('exact execution event checks once and ignores foreign binding or operation',async()=>{const f=fixture(),operation='12345678-1234-4234-8234-123456789abc';try{let handler,checks=0;f.w.c3Shell.live={on(_filter,fn){handler=fn;}};f.d.dispatchEvent(new f.w.Event('DOMContentLoaded'));sourced(f);f.proposed.status='prepared';f.w.crypto.randomUUID=()=>operation;const request=f.w.fetch;f.w.fetch=async(url,options)=>{if(new URL(url,f.w.location.href).pathname.endsWith('/run')){const start=options?.method==='POST';if(!start)checks++;return {ok:true,json:async()=>({state:start?'running':'complete',operationId:operation,requestId:f.proposed.id})};}return request(url,options);};await open(f);f.d.querySelector('[data-ai-action="run-ai"]').click();await tick();assert.equal(typeof handler,'function');handler({kind:'study-ai.execution',scope:{kind:'draft',id:'foreign'},operationId:operation,revision:f.proposed.id});handler({kind:'study-ai.execution',scope:{kind:'draft',id:f.binding.id},operationId:'other',revision:f.proposed.id});assert.equal(checks,0);f.proposed.status='pending';const event={kind:'study-ai.execution',scope:{kind:'draft',id:f.binding.id},operationId:operation,revision:f.proposed.id};handler(event);handler(event);await tick();assert.equal(checks,1);assert.ok(f.d.querySelector('[data-ai-action="apply"]'));assert.equal(f.posts.some(p=>p.action==='accept'),false);}finally{f.close();}});

