test('protected wording handoff uses the same visible margin and exact existing selection without a decision',async()=>{const f=fixture();try{const n=nativeMargin(f);await tick();const host=f.d.getElementById('study-ai-proposals'),text=n.editor.firstElementChild.firstChild,range=f.d.createRange();range.setStart(text,6);range.setEnd(text,10);f.w.getSelection().removeAllRanges();f.w.getSelection().addRange(range);n.editor.scrollTop=29;const section=await f.w.studyAIProposals.openProtectedWording();assert.equal(section,f.d.querySelector('#study-ai-proposals .study-ai-protections'));assert.equal(f.d.getElementById('study-ai-proposals'),host);assert.equal(host.closest('#margin'),n.margin);assert.equal(f.d.querySelector('.study-ai-selected-words').textContent,'kept');assert.equal(f.d.querySelector('[data-ai-action="protect-selection"]').disabled,false);assert.equal(f.w.getSelection().anchorNode,text);assert.equal(f.w.getSelection().anchorOffset,6);assert.equal(f.w.getSelection().focusOffset,10);assert.equal(n.editor.scrollTop,29);assert.equal(n.editor.textContent,'Exact kept human words.');assert.equal(f.posts.length,0);}finally{f.close();}});

