function reloadRequests(f,{state='running',status='prepared',stale=false}={}){sourced(f);f.proposed.status=status;f.proposed.instruction='Saved paragraph request';const execution={operationId:'12345678-1234-4234-8234-123456789abc',requestId:f.proposed.id,state,createdBy:'agent:codex',generatedBy:'agent:codex'};const request=f.w.fetch;f.w.fetch=async(url,options)=>new URL(url,f.w.location.href).pathname.endsWith('/requests')?{ok:true,json:async()=>({items:[{id:'older-request',purpose:'sourced-paragraph',status:'accepted',createdAt:'2026-10-30T00:00:00Z'},{id:f.proposed.id,purpose:'sourced-paragraph',status,stale,sourceIds:['source-one'],createdAt:'2026-10-31T00:00:00Z',execution}]})}:request(url,options);return execution;}
test('return restores exact running request, selected sources and instruction without a provider resend',async()=>{const f=fixture();try{reloadRequests(f);nativeMargin(f);await tick();assert.equal(f.d.querySelector('[data-ai-instruction]').value,'Saved paragraph request');assert.equal(f.d.querySelector('[data-ai-source-id="source-one"]').checked,true);assert.match(f.d.getElementById('study-ai-proposals').textContent,/Drafting/);assert.equal(f.d.querySelector('[data-ai-action="run-ai"]').disabled,true);assert.ok(f.d.querySelector('[data-ai-action="check-run"]'));assert.ok(f.d.querySelector('[data-ai-action="review:older-request"]'));assert.equal(f.posts.length,0);}finally{f.close();}});
test('return shows pending sourced paragraph immediately and does not auto-select accepted or rejected history',async()=>{const f=fixture();try{reloadRequests(f,{state:'complete',status:'pending'});nativeMargin(f);await tick();assert.ok(f.d.querySelector('.study-ai-claim'));assert.ok(f.d.querySelector('[data-ai-action="apply"]'));assert.equal(f.d.querySelector('[data-ai-action="run-ai"]'),null);assert.equal(f.posts.length,0);}finally{f.close();}for(const status of ['accepted','rejected']){const t=fixture();try{reloadRequests(t,{state:'complete',status});nativeMargin(t);await tick();assert.equal(t.d.querySelector('.study-ai-review'),null);assert.ok(t.d.querySelector('[data-ai-action="review:proposal-one"]'));assert.equal(t.posts.length,0);}finally{t.close();}}});
test('failed or interrupted saved attempts cannot rerun while preparing new work remains available',async()=>{for(const state of ['failed','interrupted']){const f=fixture();try{reloadRequests(f,{state});nativeMargin(f);await tick();const run=f.d.querySelector('[data-ai-action="run-ai"]');assert.equal(run.disabled,true);assert.equal(f.d.querySelector('[data-ai-action="prepare-sourced"]').disabled,false);run.disabled=false;run.click();await tick();assert.equal(f.posts.length,0);assert.match(f.d.querySelector('.study-ai-error').textContent,/Prepare an exact sourced paragraph first/);}finally{f.close();}}});

test('selected ending proposal precedes setup and constraints without repeating its history row',async()=>{const f=fixture();try{reloadRequests(f,{state:'complete',status:'pending'});const n=nativeMargin(f);n.native.context.records.push({id:'old-draft',title:'Retained original draft',role:'draft',copiedHash:'d'.repeat(64)});await tick();const panel=f.d.getElementById('study-ai-proposals'),review=panel.querySelector('.study-ai-review'),prepare=panel.querySelector('.study-ai-prepare'),protections=panel.querySelector('.study-ai-protections');assert.ok(review.compareDocumentPosition(prepare)&f.w.Node.DOCUMENT_POSITION_FOLLOWING);assert.ok(review.compareDocumentPosition(protections)&f.w.Node.DOCUMENT_POSITION_FOLLOWING);assert.ok(panel.querySelector('[data-ai-action="apply"]'));assert.ok(panel.querySelector('[data-ai-action="prepare-sourced"]'));assert.ok(panel.querySelector('[data-ai-action="guidance-open"]'));assert.equal(panel.querySelector('[data-ai-action="review:proposal-one"]'),null);assert.ok(panel.querySelector('[data-ai-action="review:older-request"]'));assert.equal(panel.querySelector('[data-ai-source-id="old-draft"]'),null);assert.ok(n.native.context.records.some(row=>row.id==='old-draft'));assert.equal(f.posts.length,0);}finally{f.close();}});
test('fresh native margin restores accepted paragraph citations and stand-in label beside its recorded block without approval or provider calls',async()=>{const f=fixture();try{sourced(f);Object.assign(f.proposed,{status:'accepted',stale:true,decision:{decisionRole:'stand-in',provenance:{actor:'agent:claude-code'},operations:[{kind:'insert',id:'ending',raw:'Exact kept human words.'}]}});const request=f.w.fetch;f.w.fetch=async(url,options)=>new URL(url,f.w.location.href).pathname.endsWith('/requests')?{ok:true,json:async()=>({items:[{id:f.proposed.id,purpose:'sourced-paragraph',status:'accepted',stale:true,appliedToParagraphIds:['ending'],createdAt:'2026-10-31T00:00:00Z'}]})}:request(url,options);nativeMargin(f);await tick();await tick();const panel=f.d.querySelector('#margin #study-ai-proposals');assert.ok(panel.querySelector('.study-ai-claim'));assert.ok(panel.querySelector('[data-ai-action="citation:0"]'));assert.match(panel.textContent,/Stand-in · agent:claude-code/);assert.equal(panel.dataset.endingBlock,'ending');assert.equal(panel.querySelector('[data-ai-action="apply"]'),null);assert.equal(panel.querySelector('[data-ai-action="run-ai"]'),null);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');assert.equal(f.posts.length,0);}finally{f.close();}});
test('accepted citations do not attach to a removed paragraph or another native scope',async()=>{const f=fixture();try{sourced(f);Object.assign(f.proposed,{status:'accepted',decision:{operations:[{kind:'insert',id:'removed-source-paragraph'}]}});const request=f.w.fetch;f.w.fetch=async(url,options)=>new URL(url,f.w.location.href).pathname.endsWith('/requests')?{ok:true,json:async()=>({items:[{id:f.proposed.id,purpose:'sourced-paragraph',status:'accepted',appliedToParagraphIds:['removed-source-paragraph']}]})}:request(url,options);nativeMargin(f);await tick();await tick();assert.equal(f.d.querySelector('.study-ai-review'),null);assert.equal(f.posts.length,0);assert.equal(f.d.querySelector('#manuscript').textContent,'Exact kept human words.');}finally{f.close();}});
for(const delayed of ['requests','review'])for(const returnTiming of ['before old read settles','after old read settles'])test('Read to Write reloads discarded '+delayed+' once when returning '+returnTiming,async()=>{
 const f=fixture();let release;try{
  sourced(f);Object.assign(f.proposed,{status:'accepted',stale:true,decision:{decisionRole:'stand-in',provenance:{actor:'agent:codex'},operations:[{kind:'insert',id:'ending',raw:'Exact kept human words.'}]}});
  const gate=new Promise(r=>release=r);let reached;const waiting=new Promise(r=>reached=r),request=f.w.fetch;let first=true,requestReads=0;
  f.w.fetch=async(url,options)=>{const action=new URL(url,f.w.location.href).pathname.split('/').at(-1);if(action==='requests')requestReads++;if(action===delayed&&first){first=false;reached();await gate;}if(action==='requests')return {ok:true,json:async()=>({items:[{id:f.proposed.id,purpose:'sourced-paragraph',status:'accepted',stale:true,appliedToParagraphIds:['ending'],createdAt:'2026-10-31T00:00:00Z'}]})};return request(url,options);};
  const n=nativeMargin(f),editor=n.editor;await waiting;
  f.p.viewedStage=6;f.w.studyDraft.viewMode=()=> 'preview';f.w.dispatchEvent(new f.w.Event('study-draft-change'));assert.equal(f.d.querySelector('#study-ai-proposals'),null);
  if(returnTiming==='after old read settles'){release();await tick();}
  f.p.viewedStage=5;f.w.studyDraft.viewMode=()=> 'edit';f.w.dispatchEvent(new f.w.Event('study-draft-change'));
  if(returnTiming==='before old read settles')release();await tick();await tick();
  const panel=f.d.querySelector('#margin #study-ai-proposals');assert.ok(panel);assert.doesNotMatch(panel.textContent,/Loading proposals|Loading proposal…/);assert.ok(panel.querySelector('.study-ai-claim'));assert.ok(panel.querySelector('[data-ai-action="citation:0"]'));assert.match(panel.textContent,/Stand-in · agent:codex/);assert.equal(panel.querySelectorAll('[data-ai-source-id]').length,1);assert.equal(f.w.studyAIProposals.hasExecution(),true);assert.equal(requestReads,2);assert.equal(panel.querySelector('[data-ai-action="apply"]'),null);assert.equal(f.d.getElementById('manuscript'),editor);assert.equal(editor.textContent,'Exact kept human words.');assert.equal(f.posts.length,0);
 }finally{release?.();f.close();}
});
